    const angleToggleBtn = screen.getByLabelText(/Angle unit/);
    expect(angleToggleBtn).toHaveTextContent('RADIANS');

    fireEvent.click(angleToggleBtn);
    expect(angleToggleBtn).toHaveTextContent('DEGREES');
  });

