    fireEvent.click(screen.getByRole('button', { name: 'Clear all' }));
    fireEvent.click(screen.getByRole('button', { name: 'Memory recall (MR)' }));
    expect(screen.getByLabelText(/Current expression/)).toHaveTextContent('10');

