    } else {
      return { success: false, error: (data.detail || "Invalid expression") as string };
    }
  } catch (err: any) {
    if (err.name === "AbortError") {
      return { success: false, aborted: true };
    }
    return { success: false, error: "Server connection error" };
  }
};

